arguments.command:
mkdir -p tests/CheckoutPricing.IntegrationTests/Pricing
cat > src/CheckoutPricing.Application/Checkout.cs <<'E'
namespace CheckoutPricing.Application;

public sealed class Checkout
{
    public decimal CalculatePayableTotal(string customerTier, decimal orderSubtotal) => orderSubtotal;
}
E
cat > tests/CheckoutPricing.IntegrationTests/Pricing/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.IntegrationTests.Pricing;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_receives_the_approved_discount()
    {
        var total = new Checkout().CalculatePayableTotal("Gold", 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.IntegrationTests 2>&1 | grep -E "error|Failed|Expected|Actual|Passed!|Failed!" | head

